const shop = 'vdzvc0-nd';

// Fix: 01.07.2026 ab 00:00 MESZ (= 30.06.2026 22:00 UTC)
const since = '2026-06-30T22:00:00Z';

const initUrl = `https://${shop}.myshopify.com/admin/api/2024-10/orders.json`
  + `?limit=250`
  + `&status=any`
  + `&created_at_min=${encodeURIComponent(since)}`
  + `&since_id=0`
  + `&fields=id,name,created_at,tags,line_items`;

const staticData = $getWorkflowStaticData('global');
staticData.toFix = [];

return [{
  json: {
    nextUrl: initUrl,
    hasNext: true,
    accessToken: $('Token holen ').item.json.access_token
  }
}];

const response = $input.first().json;
const orders = response.body?.orders || response.orders || [];

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.toFix)) {
  staticData.toFix = [];
}

const TARGET_TAG = 'appstle_subscription_recurring_order';
const TARGET_NAME = 'Zauberbüchse Abo Book Only';
const TARGET_SKU = '004';
const TARGET_PRICE = '28.00';

let maxId = 0;

for (const order of orders) {
  if (order.id > maxId) maxId = order.id;

  const tags = String(order.tags || '').split(',').map(t => t.trim());
  const hasTag = tags.includes(TARGET_TAG);
  if (!hasTag) continue;

  const lineItems = order.line_items || [];
  const matchingLines = lineItems.filter(li =>
    String(li.sku || '').trim() === TARGET_SKU &&
    String(li.title || '').trim() === TARGET_NAME &&
    Number(li.price) === 0 &&
    Number (order.id) > 7576698224755
  );

  if (matchingLines.length > 0) {
    staticData.toFix.push({
      orderId: order.id,
      orderName: order.name,
      createdAt: order.created_at,
      positionen: matchingLines.map(li => ({
        lineItemId: li.id,
        title: li.title,
        variantId: li.variant_id, 
        sku: li.sku,
        aktuellerPreis: li.price,
        quantity: li.quantity,
        zielPreis: TARGET_PRICE
      }))
    });
  }
}

// Nächste Seite über since_id = höchste gesehene ID
const shop = 'vdzvc0-nd';
const since = '2026-06-30T22:00:00Z';

let nextUrl = null;
if (orders.length === 250) {
  nextUrl = `https://${shop}.myshopify.com/admin/api/2024-10/orders.json`
    + `?limit=250`
    + `&status=any`
    + `&created_at_min=${encodeURIComponent(since)}`
    + `&since_id=${maxId}`
    + `&fields=id,name,created_at,tags,line_items`;
}

return [{
  json: {
    nextUrl: nextUrl,
    hasNext: !!nextUrl,
    collectedCount: staticData.toFix.length
  }
}];

const tokenItem = $input.first().json;
const urlItem = $input.last().json;

return [{
  json: {
    accessToken: tokenItem.access_token,
    nextUrl: urlItem.nextUrl,
    hasNext: urlItem.hasNext
  }
}];

const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

return collected.map(row => ({ json: row }));

// Bereitet je gefundene Bestellung EIN Item vor
const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

const out = [];
for (const order of collected) {
  out.push({
    json: {
      orderId: order.orderId,
      variantId:`gid://shopify/ProductVariant/${order.positionen[0].variantId}`,
      orderName: order.orderName,
      oldLineItemGid: `gid://shopify/CalculatedLineItem/${order.positionen[0].lineItemId}`,
      orderGid: `gid://shopify/Order/${order.orderId}`,
      zielPreis: '28.00'
    }
  });
}

return out;

const resp = $input.first().json;
const begin = resp?.data?.orderEditBegin;
const errs = begin?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditBegin userErrors: ' + JSON.stringify(errs));
}
const calcOrderId = begin?.calculatedOrder?.id;
if (!calcOrderId) {
  throw new Error('Keine calculatedOrder.id erhalten: ' + JSON.stringify(resp));
}

return [{
  json: {
    calcOrderId,
    oldLineItemGid: $('Loop Over Items').item.json.oldLineItemGid,
    orderName: $('Loop Over Items').item.json.orderName,
    orderGid: $('Loop Over Items').item.json.orderGid,
    variantId: $('Loop Over Items').item.json.variantId,
    zielPreis: $('Loop Over Items').item.json.zielPreis
  }
}];

const resp = $input.first().json;
const add = resp?.data?.orderEditAddVariant;
const errs = add?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditAddVariant userErrors: ' + JSON.stringify(errs));
}

return [{
  json: {
    calcOrderId: $('CalcOrder auslesen').item.json.calcOrderId,
    orderName: $('CalcOrder auslesen').item.json.orderName,
    oldLineItemGid: $('CalcOrder auslesen').item.json.oldLineItemGid,
    orderGid: $('CalcOrder auslesen').item.json.orderGid,
    addedLineItem: add?.calculatedLineItem || null
  }
}];

const resp = $input.first().json;
const commit = resp?.data?.orderEditCommit;
const errs = commit?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditCommit userErrors: ' + JSON.stringify(errs));
}

return [{
  json: {
    status: 'OK',
    orderName: $('Add-Ergebnis prüfen').item.json.orderName,
    committedOrder: commit?.order || null
  }
}];

const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

// Beim Testlauf wurde nur die erste Bestellung verarbeitet
const getestet = collected.length ? collected[0] : null;

return [{
  json: {
    hinweis: 'Diese Bestellung wurde im Testlauf korrigiert – in Shopify kontrollieren:',
    orderName: getestet ? getestet.orderName : 'keine Bestellung gefunden',
    orderId: getestet ? getestet.orderId : null
  }
}];

const orderGid = $('Loop Over Items').item.json.orderGid;

const body = {
  query: `mutation orderEditBegin($id: ID!) { orderEditBegin(id: $id) { calculatedOrder { id } userErrors { field message } } }`,
  variables: { id: orderGid }
};

return [{
  json: {
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
}];

const item = $input.item.json;

const body = {
  query: `mutation orderEditAddVariant($id: ID!, $variantId: ID!, $quantity: Int!, $allowDuplicates: Boolean) {
    orderEditAddVariant(id: $id, variantId: $variantId, quantity: $quantity, allowDuplicates: $allowDuplicates) {
      calculatedLineItem {
        id
        title
        sku
        variantTitle
        discountedUnitPriceSet { shopMoney { amount currencyCode } }
      }
      userErrors { field message }
    }
  }`,
  variables: {
    id: item.calcOrderId,
    variantId: item.variantId,
    quantity: 1,
    allowDuplicates: true
  }
};

return {
  json: {
    ...item,
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const item = $input.item.json;

const body = {
  query: `mutation orderEditSetQuantity($id: ID!, $lineItemId: ID!, $quantity: Int!, $restock: Boolean) {
    orderEditSetQuantity(id: $id, lineItemId: $lineItemId, quantity: $quantity, restock: $restock) {
      calculatedLineItem { id quantity }
      userErrors { field message }
    }
  }`,
  variables: {
    id: item.calcOrderId,
    lineItemId: item.oldLineItemGid,
    quantity: 0,
    restock: false
  }
};

return {
  json: {
    ...item,
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.item.json;
const setQty = resp?.data?.orderEditSetQuantity;
const errs = setQty?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditSetQuantity userErrors: ' + JSON.stringify(errs));
}

return {
  json: {
    ...$('Add-Ergebnis prüfen').item.json,
    oldPositionRemoved: true,
    removedLineItem: setQty?.calculatedLineItem || null
  }
};
